cd build && python -c "
import numpy as np
L=[l for l in open('opt_a.xyz').read().split('\n')[2:] if l.strip()]
S=[l.split()[0] for l in L]; P=np.array([[float(x) for x in l.split()[1:]] for l in L])
d=np.linalg.norm(P[:,None]-P[None],axis=-1); np.fill_diagonal(d,99)
print('min',d.min())
cov={'H':0.35,'C':0.77,'N':0.72,'P':1.08,'Cl':1.02,'Ge':1.22,'Ir':1.37}
# connectivity check
import collections
bonds=collections.defaultdict(list)
for i in range(99):
    for j in range(i+1,99):
        if d[i,j] < 1.3*(cov[S[i]]+cov[S[j]]): bonds[i].append(j); bonds[j].append(i)
for i in range(99):
    print(i,S[i],[(k,S[k],round(d[i,k],2)) for k in bonds[i]])
" > conn.txt; head -20 conn.txt; echo ---; sed -n '1,10p' conn.txt
